const enfermedadData=[{"disease":"Una reforma se aprobó con dos tercios y nunca entró en vigencia","characteristic":"Le faltó la ratificación de la legislatura siguiente","opts":["Le faltó la ratificación de la legislatura siguiente","No se publicó en La Gaceta","La vetó el Ejecutivo","Era una remisión"]},{"disease":"Se propone reformar el período presidencial con dos tercios","characteristic":"Es materia pétrea: el 374 la excluye en todo caso","opts":["Es materia pétrea: el 374 la excluye en todo caso","Falta la publicación","Hace falta mayoría simple","Lo decide el Ejecutivo"]},{"disease":"El artículo reconoce un derecho y en la práctica lo define un reglamento","characteristic":"El artículo traía una remisión y nadie la leyó","opts":["El artículo traía una remisión y nadie la leyó","El artículo es pétreo","El artículo fue derogado","Falta ratificación"]},{"disease":"Alguien cita un artículo y el texto que lee no coincide con el vigente","characteristic":"El artículo fue reformado y se citó la versión vieja","opts":["El artículo fue reformado y se citó la versión vieja","El artículo es de la parte orgánica","El artículo tiene una excepción","Es un artículo pétreo"]},{"disease":"Dicen que la Constitución ya no rige porque cambió quien manda","characteristic":"El artículo 375 dice justamente lo contrario","opts":["El artículo 375 dice justamente lo contrario","Es correcto si hay acuerdo","Depende del Congreso","Solo aplica a las transitorias"]},{"disease":"Se busca el régimen de la educación en el título de las garantías","characteristic":"Es problema de mapa: se está buscando en el título equivocado","opts":["Es problema de mapa: se está buscando en el título equivocado","El artículo fue derogado","Falta ratificación","Es materia pétrea"]}];
let enferIdx=0,enferDone=false;
function showEnfer(){enferDone=false;if(enferIdx>=enfermedadData.length){const el=document.getElementById('enferDisease');if(el)el.textContent='🎉 ¡Completado!';const opts=document.getElementById('enferOpts');if(opts)opts.innerHTML='';return;}const d=enfermedadData[enferIdx];const prog=document.getElementById('enferProg');if(prog)prog.textContent=`${enferIdx+1} de ${enfermedadData.length}`;const dis=document.getElementById('enferDisease');if(dis)dis.textContent=d.disease;const opts=document.getElementById('enferOpts');if(!opts)return;opts.innerHTML='';_shuffle([...d.opts]).forEach(opt=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=opt;b.onclick=()=>checkEnfer(opt,b,d);opts.appendChild(b);});const fbEl=document.getElementById('fbEnfer');if(fbEl)fbEl.classList.remove('show');}
function checkEnfer(opt,btn,d){if(enferDone)return;enferDone=true;document.querySelectorAll('#enferOpts .qz-opt').forEach(b=>{if(b.textContent===d.characteristic)b.classList.add('correct');else if(b===btn&&b.textContent!==d.characteristic)b.classList.add('wrong');});const isOk=opt===d.characteristic;if(isOk){fb('fbEnfer','¡Correcto! +3 XP',true);if(!xpTracker.wgt.has('enfer_'+enferIdx)){xpTracker.wgt.add('enfer_'+enferIdx);pts(3);}sfx('ok');}else{fb('fbEnfer','Correcto: '+d.characteristic,false);sfx('no');}setTimeout(()=>{enferIdx++;showEnfer();},1800);}
function resetEnfer(){sfx('click');enferIdx=0;showEnfer();}

