function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"Un maestro entusiasmado propone «pedir que reformen la Constitución» para que M.E.T.A.S sea de uso obligatorio en las escuelas del departamento."},{"txt":"Un convenio que le ofrecen al proyecto dice que el material se usará «conforme a la reglamentación vigente», sin decir cuál es esa reglamentación ni quién la dicta."},{"txt":"En año electoral, un diputado ofrece imprimir cinco mil fichas de M.E.T.A.S con su cara en la portada, y de paso pide que el proyecto lo acompañe a dos actos."},{"txt":"Alguien le asegura a la familia que «la Constitución dice que la educación la autoriza exclusivamente la Secretaría», y cita el artículo 157 de memoria, sin decir de qué año es el texto que leyó."},{"txt":"Un acuerdo de una Secretaría se ampara en la frase «conforme lo determine la ley» de un artículo de derechos, y resulta que esa ley nunca se dictó."},{"txt":"Después de un cambio de gobierno, en una oficina le dicen al proyecto que «esa Constitución ya no aplica» y que hay que esperar a que se ordene todo."},{"txt":"Se celebra en la prensa que el Congreso aprobó una reforma que beneficiaría al proyecto. Nadie menciona la legislatura siguiente ni la ratificación."},{"txt":"Le presentan al proyecto un «reglamento» que en realidad cambia lo que dice una ley, y lo defienden diciendo que la Constitución permite reglamentar."}];
const critCaseQuestions=["1. ¿En qué título de la Constitución vive lo que está en juego, y qué artículo lo trata?","2. Si hay una reforma de por medio: ¿cumple el artículo 373, y podría chocar con el 374?","3. ¿El texto que le citaron trae alguna remisión? ¿A qué norma manda, y esa norma existe?","4. ¿Qué comprueba antes de contestar, y qué apunta para no tener que comprobarlo otra vez?"];
const critCaseGuides=["Ubicar el título es más rápido de lo que parece y ahorra discusiones enteras: del I al IV está la parte dogmática (Estado, nacionalidad, derechos y garantías) y del V al VI la orgánica (poderes y régimen económico); el VII es la reforma y la inviolabilidad, y el VIII las transitorias. Si lo que discuten es un derecho y alguien lo busca en el título de los poderes, el problema no es de interpretación: es de mapa.","El artículo 373 pide tres cosas a la vez, y la que se olvida siempre es la tercera: sesiones ordinarias, dos tercios de la totalidad de los miembros, decreto que señale qué artículos se reforman, y ratificación por la subsiguiente legislatura ordinaria por igual número de votos. Sin ratificación no hay vigencia, por mucho que se haya celebrado. Y antes de contar votos conviene mirar el 374, porque hay materias donde el procedimiento no alcanza: si lo que se quiere tocar está ahí, la respuesta no es «cuesta más», es «no por esta vía».","La remisión es la pieza que convierte un artículo generoso en una promesa a cargo de otro. Cuando el texto dice «conforme lo determine la ley», el contenido real lo escribirá esa ley, y hay que preguntar dos cosas: cuál es, y si existe. Una remisión a una ley que nunca se dictó deja el derecho en el papel y a la administración con las manos libres, que es exactamente el tipo de hueco que va al Registro de Grietas.","Se comprueba el texto en fuente oficial, se mira el decreto de reforma y desde cuándo rige, y se apunta norma, artículo, decreto y fecha de consulta. Cinco minutos. Discutir el fondo de un artículo sin comprobarlo es apostar la credibilidad de todo lo demás que se va a decir, y esa apuesta se pierde delante de la única persona que sí lo había leído."];

const critErrorBank=[{"txt":"\"El Congreso ya aprobó la reforma con dos tercios, así que ya es ley\".","g1":"Falta la mitad del procedimiento. El artículo 373 pide que la subsiguiente legislatura ordinaria la ratifique por igual número de votos para que entre en vigencia.","g2":"El habeas data del artículo 182 es el ejemplo: el intento de 2005 se cayó exactamente ahí, y el que sí prosperó necesitó los dos votos, en 2012 y 2013."},{"txt":"\"Si hay votos suficientes, se puede reformar cualquier artículo\".","g1":"No. El artículo 374 excluye materias enteras en todo caso: forma de gobierno, territorio, período presidencial y la prohibición de repetir en la Presidencia, entre otras.","g2":"Y se excluye a sí mismo y al 373, que es lo más fino: si no lo hiciera, bastaría con reformar primero el candado para poder abrir después todo lo demás."},{"txt":"\"El artículo reconoce el derecho, así que el derecho está garantizado\".","g1":"Depende de si trae remisión. «Conforme lo determine la ley» significa que el contenido real lo escribe otra norma, casi siempre un escalón más abajo.","g2":"Y si esa ley nunca se dictó, el derecho queda en el papel. Eso no es un detalle de redacción: es dónde se decide de verdad lo que uno puede exigir."},{"txt":"\"Cambió el gobierno, así que hay que esperar a ver qué Constitución rige\".","g1":"El artículo 375 dice justamente lo contrario: no pierde vigencia ni deja de cumplirse por acto de fuerza ni por una derogación hecha por un medio distinto del que ella dispone.","g2":"Y añade algo que casi nadie cita: el deber de todo ciudadano, con autoridad o sin ella, de colaborar en el restablecimiento de su vigencia."},{"txt":"\"Me lo dijo alguien que sabe, y citó el artículo de memoria\".","g1":"Un artículo es un texto con fecha. El mismo número puede decir hoy algo distinto de lo que decía hace diez años, porque lo reformaron.","g2":"Comprobarlo cuesta cinco minutos y protege lo que viene después: quien cita mal un número pierde también la credibilidad de todo lo demás que iba a decir."},{"txt":"\"Honduras ha tenido dieciséis constituciones, es un dato conocido\".","g1":"Es un dato discutido. Hay fuentes que dicen doce, otras catorce y otras dieciséis, según si se cuentan los textos del período federal y si una reforma muy grande cuenta como texto nuevo.","g2":"Contado como discutido, es información útil sobre la historia del país. Contado como cierto, es una trampa que estalla en la primera reunión donde alguien conozca el tema."}];

const critDecisionBank=["Proponen pedir una reforma constitucional para que M.E.T.A.S sea obligatorio: ¿cuánto tarda como mínimo y qué pasos hay que contar antes de decir que sí?","Un convenio remite a «la reglamentación vigente» sin nombrarla: ¿se firma, se pregunta o se propone otra redacción? ¿Qué se propone exactamente?","Un artículo de derechos remite a una ley que nunca se dictó: ¿qué se puede exigir mientras tanto y qué se apunta en el Registro de Grietas?","Le citan un artículo de memoria en una reunión y no cuadra con lo que usted leyó: ¿qué contesta ahí mismo, sin dejar a nadie en mal lugar?","Un diputado ofrece imprimir fichas en año electoral: ¿qué del artículo 4 conviene tener presente y qué condición se pone antes de aceptar algo?","Se celebra una reforma aprobada que beneficia al proyecto: ¿se cuenta con ella desde ya o se espera? ¿A qué exactamente?","Un reglamento cambia lo que dice una ley y lo defienden diciendo que reglamentar está permitido: ¿dónde está el error y cómo se dice en una línea?","En una oficina dicen que la Constitución «no aplica» tras un cambio de gobierno: ¿qué artículo se cita y cómo se cita sin convertirlo en pelea?"];
const critDecisionGuide='La decisión correcta en esta etapa sigue siempre el mismo orden: primero se nombra el dato que cruza la frontera y de dónde viene; después se escribe la comprobación como lista permitida y se pone del lado del servidor, que es el que el usuario no puede editar; después se decide qué pasa cuando la comprobación no se puede hacer, y ahí se falla cerrado, nunca en silencio; y al final se rompe la comprobación a propósito para ver que de verdad se pone roja. Si el fallo no se puede oír, todavía no está resuelto.';

const critCompareBank=[{"a":"Esperar a la ratificación de la legislatura siguiente antes de contar con una reforma.","b":"Empezar a planificar el proyecto como si la reforma ya rigiera.","ga":"Caso A: el artículo 373 dice que sin ratificación no hay vigencia. Esperar no cuesta nada y evita construir sobre algo que puede no existir nunca.","gb":"Caso B: si no se ratifica, se pierde el trabajo hecho y, peor, se prometieron cosas a maestros y madres que después hay que retirar."},{"a":"Pedir que el convenio nombre la reglamentación exacta a la que remite.","b":"Firmar el convenio con la frase «conforme a la reglamentación vigente».","ga":"Caso A: se sabe qué se está aceptando, y si la reglamentación cambia, se sabe qué cambió y desde cuándo.","gb":"Caso B: se firma un contenido que otro escribirá después, sin decir quién ni cuándo. La remisión funciona igual en un contrato que en la Constitución."},{"a":"Comprobar el artículo antes de discutirlo.","b":"Discutir el fondo del artículo con lo que uno recuerda.","ga":"Caso A: cinco minutos, y se entra a la conversación con el texto y su fecha. Cambia quién tiene que probar qué.","gb":"Caso B: si el número o la versión están mal, se pierde el punto y con él lo demás. Es lo que esta ruta prohíbe expresamente."},{"a":"Decir que el dato de las constituciones está discutido y explicar por qué.","b":"Elegir el número que suena mejor y decirlo con seguridad.","ga":"Caso A: se enseña algo verdadero sobre la historia del país y sobre cómo se cuenta la historia.","gb":"Caso B: se gana una frase redonda y se pierde la primera vez que aparezca alguien que conozca el tema."}];

const critCauseBank=[{"cause":"Se cuenta con una reforma aprobada pero no ratificada.","guide":"El proyecto planifica sobre algo que puede no llegar a existir, y si no se ratifica hay que retirar promesas ya hechas a maestros y a madres. El artículo 373 avisaba."},{"cause":"Se firma un convenio que remite a «la reglamentación vigente» sin nombrarla.","guide":"Se acepta un contenido que escribirá otro después. La remisión funciona igual en un contrato que en la Constitución, y aquí el que la escribe no es la casa."},{"cause":"Se repite un artículo citado de memoria por alguien de confianza.","guide":"Si el texto fue reformado, se repite una versión que ya no rige, y el error viaja con el prestigio de quien lo dijo. Después es más difícil deshacerlo."},{"cause":"Se busca un tema en el título equivocado y se concluye que la Constitución no dice nada.","guide":"Se toma por vacío lo que solo estaba en otra parte del mapa. Del I al IV va lo dogmático, del V al VI lo orgánico, el VII la reforma y el VIII las transitorias."},{"cause":"Se acepta que un reglamento cambie lo que dice una ley porque «reglamentar está permitido».","guide":"Reglamentar es desarrollar la ley para poder aplicarla, no ampliarla ni recortarla. El escalón de la etapa 1 vuelve aquí, ahora con la Constitución encima."},{"cause":"Se da por buena la frase «esa Constitución ya no aplica» tras un cambio de gobierno.","guide":"El artículo 375 dice lo contrario, y quien lo desconoce suele estar pidiendo algo que no podría pedir si la Constitución se aplicara."}];
const critEffectBank=[{"effect":"El proyecto no se apuntó a una reforma que al final nunca entró en vigencia.","guide":"Se contaron los pasos del artículo 373 antes de celebrar, y faltaba el segundo voto. Se esperó a la ratificación, que nunca llegó."},{"effect":"El convenio quedó firmado nombrando exactamente qué reglamento lo rige.","guide":"Se pidió cambiar «conforme a la reglamentación vigente» por el nombre y la fecha de la norma. Cinco palabras más y se sabe qué se aceptó."},{"effect":"En la reunión se citó un artículo y nadie pudo desmentirlo.","guide":"Se había comprobado el texto vigente y su decreto de reforma, y se llevó anotada la fecha de consulta."},{"effect":"La familia supo qué exigir aunque la ley prometida no existiera.","guide":"Se detectó la remisión, se buscó la norma a la que mandaba y se comprobó que no se había dictado. Eso se apuntó como grieta, con su ficha."},{"effect":"La oferta del diputado se aceptó a medias y sin quedar amarrado.","guide":"Se separó lo que aporta (impresión) de lo que compromete (presencia en actos), y se puso por escrito qué no se cede: el nombre del autor y la neutralidad del material."},{"effect":"Nadie volvió a decir en esa oficina que la Constitución no aplicaba.","guide":"Se citó el artículo 375 con su texto, sin levantar la voz, y se pidió por escrito la respuesta. El argumento no volvió a aparecer."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 El artículo sobre la mesa · Forma ${cf} · Anatomía de la Constitución de 1982 · Ruta de la Ley y sus Grietas`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. El artículo sobre la mesa <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿En qué título vive lo que está en juego, el texto trae alguna remisión y, si hay reforma de por medio, cumple el artículo 373 sin chocar con el 374? Explica qué comprobarías antes de contestar.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de los dos se sostiene con el texto comprobado en la mano? 2. ¿Por qué no son la misma decisión?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0 a 20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 El artículo sobre la mesa: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. El artículo sobre la mesa</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿En qué título vive lo que está en juego, el texto trae alguna remisión y, si hay reforma de por medio, cumple el artículo 373 sin chocar con el 374? Explica qué comprobarías antes de contestar.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de los dos se sostiene con el texto comprobado en la mano? 2. ¿Por qué no son la misma decisión?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>El artículo sobre la mesa Anatomía de la Constitución de 1982 · Ruta de la Ley y sus Grietas · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · El artículo sobre la mesa · Anatomía de la Constitución de 1982 · Ruta de la Ley y sus Grietas · Etapa 2 · Derecho y Ley</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: El artículo sobre la mesa · Anatomía de la Constitución de 1982 · Ruta de la Ley y sus Grietas · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1","icon":"📜","label":"El decreto y la fecha","text":"La Constitución vigente es el <strong>Decreto 131 del 11 de enero de 1982</strong>, publicada en La Gaceta 23,612 del 20 de enero. <strong>Sirve para:</strong> citar el texto exacto. <strong>Se pierde:</strong> diciendo «la Constitución dice» sin saber de qué versión se habla."},{"y":"2","icon":"🗺️","label":"El mapa","text":"<strong>8 títulos, 43 capítulos, 378 artículos.</strong> <strong>Sirve para:</strong> encontrar en un minuto lo que si no cuesta media hora. <strong>Se pierde:</strong> buscando un derecho en el título de los poderes y concluyendo que la Constitución no dice nada."},{"y":"3","icon":"🙋","label":"La parte dogmática","text":"Títulos I a IV: el Estado, la nacionalidad, los derechos y sus garantías. <strong>Es la parte que habla de ti.</strong> <strong>Se pierde:</strong> leyendo solo esta y creyendo que ya se leyó la Constitución."},{"y":"4","icon":"🏛️","label":"La parte orgánica","text":"Títulos V y VI: los poderes del Estado y el régimen económico. <strong>Es la parte que habla de quién manda</strong>, y la que casi nadie lee aunque decide más. <strong>Aquí:</strong> es donde se ve quién puede decir que sí de verdad."},{"y":"5","icon":"🧩","label":"El artículo por dentro","text":"Cuatro piezas: <strong>supuesto de hecho, consecuencia, excepción y remisión</strong>. <strong>Sirve para:</strong> saber si el artículo habla de tu caso. <strong>Se pierde:</strong> quedándose con la primera frase, que es la que suena bien."},{"y":"6","icon":"➡️","label":"La remisión","text":"Cuando el artículo <strong>manda a otra norma</strong> a completar lo que él no dice. <strong>Se reconoce:</strong> «conforme lo determine la ley». <strong>Se pierde:</strong> celebrando un derecho cuyo contenido real lo escribirá un reglamento."},{"y":"7","icon":"🪨","label":"La reforma y el candado","text":"<strong>Art. 373:</strong> dos tercios y ratificación por la legislatura siguiente. <strong>Art. 374:</strong> lo que no se reforma en ningún caso, incluido él mismo. <strong>Art. 375:</strong> no pierde vigencia por acto de fuerza."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(esperaRatificacion){sfx(esperaRatificacion?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(esperaRatificacion){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">⏳</span><span class="ms-text"><strong>Contaste los dos votos:</strong> el artículo 373 pide que la subsiguiente legislatura ordinaria ratifique por igual número de votos. Todavía falta el segundo, así que no hay vigencia.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">✅</span><span class="ms-text"><strong>Y no prometiste nada:</strong> la reforma no se ratificó. Nadie tuvo que retirar lo dicho a los maestros, y el proyecto no perdió el trabajo de planificar sobre algo que no llegó.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🎉</span><span class="ms-text"><strong>Lo diste por hecho:</strong> se anunció en la reunión de padres, se cambió el plan del año y se le dijo a tres maestros que contaran con ello.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📉</span><span class="ms-text"><strong>Y la legislatura siguiente no ratificó:</strong> la reforma nunca entró en vigencia. Hubo que retirar lo prometido, que cuesta mucho más que no haberlo prometido.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"mapa":{"nombre":"El mapa de los títulos","icon":"🗺️","estructura":{"title":"Qué es","info":"• <strong>8 títulos, 43 capítulos y 378 artículos</strong><br>• I Organización del Estado · II Nacionalidad y Ciudadanía<br>• III Declaraciones, Derechos y Garantías · IV Garantías Constitucionales<br>• V Poderes del Estado · VI Régimen Económico<br>• VII Reforma e Inviolabilidad · VIII Transitorias y Vigencia"},"funcion":{"title":"Cómo se usa","info":"• Antes de buscar un artículo, se decide <strong>en qué título debería vivir</strong><br>• Del I al IV es la parte dogmática; el V y el VI, la orgánica<br>• Si el tema no aparece donde debería, casi siempre está en el título de al lado"},"enfermedades":{"title":"Dónde se cae","info":"• Buscando un derecho en el título de los poderes y creyendo que no existe<br>• Citando un artículo sin mirar de qué capítulo sale, que es lo que dice de qué trata<br>• Leyendo solo la parte dogmática y creyendo que ya se leyó la Constitución"},"cuidados":{"title":"En este proyecto","info":"• La educación toca <strong>derechos</strong> (título III) y <strong>poderes</strong> (título V) a la vez<br>• Las garantías con las que se defiende algo están en el <strong>IV</strong><br>• Y lo que puede cambiar todo esto, en el <strong>VII</strong>"}},"articulo":{"nombre":"El artículo por dentro","icon":"🧩","estructura":{"title":"Qué es","info":"• <strong>Supuesto de hecho:</strong> en qué caso se aplica<br>• <strong>Consecuencia:</strong> qué pasa entonces<br>• <strong>Excepción:</strong> el caso que queda fuera<br>• <strong>Remisión:</strong> a qué otra norma manda"},"funcion":{"title":"Cómo se usa","info":"• Se lee entero una vez, sin subrayar<br>• Se marca cada pieza con un color distinto<br>• Se pregunta: <strong>¿mi caso encaja en el supuesto?</strong> Si no encaja, el artículo no habla de mí"},"enfermedades":{"title":"Dónde se cae","info":"• Quedándose con la primera frase, que es la que suena bien<br>• No buscando el «salvo», que es lo primero que busca quien va a decir que no<br>• Pasando por alto la remisión, que es donde se decide el contenido real"},"cuidados":{"title":"En este proyecto","info":"• El artículo <strong>157</strong> se lee así en la etapa 5, pieza por pieza<br>• Un convenio se lee igual: también tiene supuesto, consecuencia y remisiones<br>• Lo que sale de leer así se apunta en el <strong>Registro de Grietas</strong>"}},"remision":{"nombre":"La remisión","icon":"➡️","estructura":{"title":"Qué es","info":"• La pieza por la que el artículo <strong>manda a otra norma</strong> a completarlo<br>• «Conforme lo determine la ley», «en los casos que la ley señale»<br>• El artículo parece haber decidido y no decidió"},"funcion":{"title":"Cómo se usa","info":"• Se subraya en rojo apenas aparece<br>• Se pregunta <strong>a qué norma manda</strong> y si esa norma existe<br>• Se busca esa norma, porque ahí está el contenido real del derecho"},"enfermedades":{"title":"Dónde se cae","info":"• Celebrando el derecho reconocido sin mirar quién lo va a definir<br>• Aceptando una remisión a una ley que nunca se dictó<br>• Firmando un convenio que remite a «la reglamentación vigente» sin nombrarla"},"cuidados":{"title":"En este proyecto","info":"• Todo convenio que le llegue a esta casa se revisa <strong>buscando remisiones</strong><br>• Si remite, se pide que <strong>nombre la norma y su fecha</strong><br>• Una remisión a una ley inexistente va derecha al Registro de Grietas"}},"reforma":{"nombre":"La reforma y el candado","icon":"🪨","estructura":{"title":"Qué es","info":"• <strong>Art. 373:</strong> sesiones ordinarias, dos tercios de la totalidad, decreto que señale qué artículos, y <strong>ratificación</strong> por la subsiguiente legislatura ordinaria<br>• <strong>Art. 374:</strong> lo que no se reforma en ningún caso<br>• <strong>Art. 375:</strong> no pierde vigencia por acto de fuerza"},"funcion":{"title":"Cómo se usa","info":"• Ante cualquier reforma anunciada se cuentan <strong>los dos votos</strong><br>• Antes de contar votos se mira el 374: si la materia está ahí, no es cuestión de esfuerzo<br>• Y ante un «ya no aplica», se cita el 375"},"enfermedades":{"title":"Dónde se cae","info":"• Dando por vigente una reforma aprobada <strong>una sola vez</strong><br>• Creyendo que con votos suficientes se puede reformar cualquier cosa<br>• Olvidando que el 374 <strong>se protege a sí mismo</strong> y al 373"},"cuidados":{"title":"En este proyecto","info":"• El <strong>habeas data</strong> es el ejemplo real: cayó en 2005 por falta de ratificación y prosperó con 237-2012 y 10-2013<br>• Ninguna promesa de reforma se planifica hasta el segundo voto<br>• Lo que el 374 protege se estudia entero en la <strong>etapa 6</strong>"}}};
let labParte='mapa',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue estudiando tu sistema!','¡Muy buen trabajo!','¡Excelente gestor en formación!','¡Sabes por dónde se mueve esto!','¡Estratega institucional!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='📜 ¡'+name+' completó la Etapa 2 de la Ruta de la Ley y sus Grietas (Anatomía de la Constitución de 1982)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

